import {dayNumber,shiftDate} from './age.js';
import {CalculatorError} from './calculator-params.js';
export const FAMILY_RECORD_STATUSES={planned:'Planowany',requested:'Złożono wniosek',approved:'Zatwierdzony — według podanych dokumentów',used:'Wykorzystany',paid:'Wypłacony'};
export function normalizeFamilyHistory(raw=[]){if(!Array.isArray(raw)||raw.length>500)throw new CalculatorError('Historia rodziny może zawierać do 500 okresów.');return raw.map(r=>{if(!r||!FAMILY_RECORD_STATUSES[r.status]||!['family','care','sickness','rehab','prebirth','business'].includes(r.focus))throw new CalculatorError('Nieprawidłowy rodzaj okresu w historii.');dayNumber(r.start);dayNumber(r.end);if(r.end<r.start||dayNumber(r.end)-dayNumber(r.start)>2000)throw new CalculatorError('Sprawdź okres zapisanej historii.');const text=x=>String(x||'').slice(0,100);const rate=r.rate==null?null:Number(r.rate);if(rate!==null&&(!Number.isFinite(rate)||rate<0||rate>100))throw new CalculatorError('Nieprawidłowa stawka w historii rodziny.');const poolFraction=r.poolFraction==null?1:Number(r.poolFraction);if(!Number.isFinite(poolFraction)||poolFraction<=0||poolFraction>1)throw new CalculatorError('Nieprawidłowy udział wykorzystania puli.');return {rate,poolFraction,exclusive:r.exclusive!==false,id:text(r.id),caseId:text(r.caseId),focus:r.focus,status:r.status,personId:text(r.personId),childKey:text(r.childKey),kind:['maternity','parental','paternity','care','other'].includes(r.kind)?r.kind:'other',careType:text(r.careType),start:r.start,end:r.end,days:dayNumber(r.end)-dayNumber(r.start)+1};});}
export function familyLedger(snapshot,excludeId='',includeDemo=false){return normalizeFamilyHistory(snapshot.cases.filter(c=>c.id!==excludeId&&(c.input.dataOrigin==='demo')===includeDemo).flatMap(c=>c.result.periods.filter(p=>p.kind!=='information').map(p=>({rate:p.rate,poolFraction:1-(p.work||0),exclusive:!p.id.startsWith('funeral'),id:c.id+'-'+p.id,caseId:c.id,focus:c.input.focus,status:c.status||c.input.formalCase?.recordStatus||'planned',personId:c.input.formalCase?.personIds?.[p.parent]||'parent-'+(p.parent+1),childKey:c.input.formalCase?.childReference||[c.input.sourceSituationId||'',c.input.sourceChildId||c.input.childBirthDate||c.input.eventDate].join(':'),kind:p.id.startsWith('parental')||p.id.startsWith('extension')?'parental':p.id.startsWith('paternity')?'paternity':p.id.startsWith('maternity')?'maternity':c.input.focus==='care'?'care':'other',careType:c.input.care?.type==='disabled-child'&&c.input.formalCase?.careReason==='sick'&&c.input.care.ageMonths<168?'sick-child':c.input.care?.type==='sick-child'&&c.input.care.ageMonths>=168?'sick-child-older':c.input.care?.type||'',start:p.start,end:p.end}))));}
export function ledgerUnionDays(records,from,to){const days=new Set();for(const r of records){let a=r.start<from?from:r.start;const end=r.end>to?to:r.end;while(a<=end){days.add(a);a=shiftDate(a,1);}}return days.size;}
export function ledgerFamilyDays(records,from,to){return [...new Set(records.map(r=>r.personId))].reduce((sum,id)=>sum+ledgerUnionDays(records.filter(r=>r.personId===id),from,to),0);}
export function applyFamilyHistory(input,history){const used=history.filter(r=>['used','paid'].includes(r.status)),notes=[],year=(input.care.start||input.eventDate).slice(0,4);if(input.focus==='care'){const care=used.filter(r=>r.focus==='care'&&r.careType!=='extra-newborn'),all=ledgerFamilyDays(care,year+'-01-01',year+'-12-31'),disabled=ledgerFamilyDays(care.filter(r=>r.careType==='disabled-child'),year+'-01-01',year+'-12-31'),adult=ledgerFamilyDays(care.filter(r=>r.careType==='adult'||r.careType==='sick-child-older'),year+'-01-01',year+'-12-31');input.care.usedAll=Math.max(input.care.usedAll,all);input.care.usedDisabled=Math.max(input.care.usedDisabled,disabled);input.care.usedAdult=Math.max(input.care.usedAdult,adult);if(all)notes.push('Wspólny limit opieki uwzględnia '+all+' dni z zapisanych okresów wykorzystanych/wypłaconych. Ręczne sumy traktujemy jako obejmujące tę historię, nie dodajemy jej drugi raz.');}
 if(input.focus==='family'){const childKey=input.formalCase.childReference||[input.sourceSituationId||'',input.sourceChildId||input.childBirthDate||input.eventDate].join(':'),own=used.filter(r=>r.childKey===childKey);input.previousMaternityDays=Math.max(input.previousMaternityDays,ledgerUnionDays(own.filter(r=>r.kind==='maternity'),'1900-01-01','2100-12-31'));for(let p=0;p<2;p++){const field=p?'previousParent2Days':'previousParent1Days',records=own.filter(r=>r.kind==='parental'&&r.personId===input.formalCase.personIds[p]);input[field]=Math.max(input[field],ledgerPoolDays(records));}input.historyParentalPeriods=own.filter(r=>r.kind==='parental');input.historyMaternityPeriods=own.filter(r=>r.kind==='maternity');input.previousParts=Math.max(input.previousParts,[0,1].map(p=>ledgerPartCount(own.filter(r=>r.kind==='parental'&&r.personId===input.formalCase.personIds[p]))).reduce((n,x)=>n+x,0));if(own.length)input.previousParentDays=input.previousParent1Days+input.previousParent2Days;if(own.length)notes.push('Wykorzystane okresy tego samego dziecka pomniejszają wspólną pulę. Daty tej samej osoby łączymy bez podwajania, a ręczne sumy traktujemy jako obejmujące historię. Sprawdź również okresy spoza aplikacji.');}
 return notes;}
export function familyConflicts(input,periods,history){const conflicts=[];for(const p of periods.filter(p=>p.kind!=='information'))for(const h of history){if(!h.exclusive||h.personId!==input.formalCase.personIds[p.parent]||p.start>h.end||h.start>p.end)continue;conflicts.push({caseId:h.caseId,start:p.start>h.start?p.start:h.start,end:p.end<h.end?p.end:h.end,blocking:['used','paid','approved','requested'].includes(h.status),message:['planned'].includes(h.status)?'Inny plan obejmuje ten sam okres tej osoby. Traktuj je jako alternatywy, nie dwie wypłaty.':'Okres nakłada się na inną zapisaną sprawę tej samej osoby. Potrzebna jest weryfikacja zbiegu i aktualnej historii.'});}return conflicts;}
export function compareCalculatorResults(previous,current){if(!previous)return [];const changes=[];if(previous.rulesVersion!==current.rulesVersion)changes.push('Zmiana wersji zasad: '+previous.rulesVersion+' → '+current.rulesVersion);for(let p=0;p<2;p++)if(previous.totals?.[p]?.gross!==current.totals?.[p]?.gross)changes.push('Osoba '+(p+1)+': zmieniła się łączna kwota brutto lub możliwość jej ustalenia.');if(JSON.stringify(previous.periods?.map(p=>[p.start,p.end]))!==JSON.stringify(current.periods?.map(p=>[p.start,p.end])))changes.push('Zmieniły się okresy — sprawdź wszystkie zależne wnioski i terminy kalendarza.');return changes;}

export function ledgerPoolDays(records){const days=new Map();for(const r of records)for(let date=r.start;date<=r.end;date=shiftDate(date,1))days.set(date,Math.max(days.get(date)||0,r.poolFraction??1));return Math.round([...days.values()].reduce((n,x)=>n+x,0)*1e6)/1e6;}
export function ledgerPartCount(records){const sorted=[...records].sort((a,b)=>a.start.localeCompare(b.start));let count=0,end='';for(const r of sorted){if(!end||r.start>shiftDate(end,1))count++;if(r.end>end)end=r.end;}return count;}
export function knownMaternityContinuation(input){if(input.familyType!=='birth'||input.transfer!=='none'||input.loss!=='none'||input.motherPauseStart||!input.formalCase.historyComplete||!input.previousMaternityDays)return null;const r=input.historyMaternityPeriods||[],start=shiftDate(input.eventDate,-input.prenatalDays),last=shiftDate(start,input.previousMaternityDays-1);if(!r.length||r.some(p=>p.start<start||p.end>last)||ledgerUnionDays(r,start,last)!==input.previousMaternityDays)return null;return {start:shiftDate(last,1),used:input.previousMaternityDays};}
